{
  "findings": [
    {
      "check_id": "CKV_AWS_3",
      "title": "Ensure all data stored in the EBS is securely encrypted",
      "resource": "aws_ebs_volume.changeme_simple_aws_ebs_volume",
      "severity": "MEDIUM",
      "explanation": "The EBS volume is not encrypted, which means data stored on it is vulnerable to unauthorized access if the volume is compromised."
    },
    {
      "check_id": "CKV_AWS_189",
      "title": "Ensure EBS Volume is encrypted by KMS using a customer managed Key (CMK)",
      "resource": "aws_ebs_volume.changeme_simple_aws_ebs_volume",
      "severity": "MEDIUM",
      "explanation": "The EBS volume is not encrypted using a customer-managed KMS key, which limits control over encryption and key management policies."
    }
  ],
  "patched_code": "resource \"aws_ebs_volume\" \"changeme_simple_aws_ebs_volume\" {\n  availability_zone = data.aws_availability_zones.changeme_available_az_list.names[0]\n  size              = 10\n  type              = \"standard\"\n  encrypted         = true\n  kms_key_id        = aws_kms_key.changeme_ebs_kms_key.arn\n}\n\nresource \"aws_kms_key\" \"changeme_ebs_kms_key\" {\n  description             = \"KMS key for EBS volume encryption\"\n  enable_key_rotation     = true\n}\n",
  "fix_summary": "Enabled encryption for the EBS volume and specified a customer-managed KMS key to enhance data security and control over encryption policies."
}
